R=Path(__file__).resolve().parents[1];p=R/'analysis/v192_normalized_partition_complementary_boolean_checks.json';d=json.loads(p.read_text());H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();assert d['status']=='NORMALIZED_PARTITION_COMPLEMENTARY_NATIVE_BOOLEAN_CHECKS_MEASURED' and d['stage']=='complete';assert d['union_native_valid'] and d['union_solids']==1
