differences=[d['source_minus_union'],d['union_minus_source']];out=R/'analysis/v192_normalized_partition_complementary_verification.json';assert not out.exists();out.write_text(json.dumps({'status':'COMPLEMENTARY_BOOLEAN_REPORT_HASHES_AND_NUMERIC_RESULTS_VERIFIED','input_report_sha256':H(p),'union_native_exact_method_valid':d['union_native_exact_method_valid'],'both_native_differences_have_no_solids_or_faces':all(x['solids']==0 and x['faces']==0 for x in differences),'max_absolute_difference_volume_mm3':max(abs(x['volume_mm3']) for x in differences),'max_difference_area_mm2':max(x['area_mm2'] for x in differences),'default_union_minus_source_mm3':d['default_union_minus_source_mm3'],'GK_union_minus_source_mm3':d['GK_union_minus_source_mm3'],'default_balance_within1e_minus5':abs(d['default_union_minus_source_mm3'])<1e-5,'GK_balance_within1e_minus5':abs(d['GK_union_minus_source_mm3'])<1e-5,'limits':['Native Boolean emptiness not rigorous exact boundary identity or absolute accuracy proof','Default/adaptive method discrepancy retained; no candidate or method promotion','Updated seam, structural, OML, exported mesh and manufacturing checks remain open'],'print_release':False,'flight_release':False},indent=2)+'\n');print('Complementary Boolean report verified')
